// ❌ OLD: Complex 2D/3D physics or particle rendering on the main thread
// causes frame drops whenever the user interacts or DOM updates occur.
const canvas = document.getElementById('my-canvas');
const ctx = canvas.getContext('2d');

function render() {
  draw10000Particles(ctx);
  requestAnimationFrame(render); // Stutters on heavy JS work
}
render();

// ✅ NEW: Transfer canvas control to a background Worker.
// The main thread is 100% free from graphics rendering overhead.
const canvas = document.getElementById('my-canvas');
const offscreen = canvas.transferControlToOffscreen();

const worker = new Worker(new URL('./canvas.worker.js', import.meta.url), { type: 'module' });

// Zero-copy transfer of canvas control:
worker.postMessage({ canvas: offscreen }, [offscreen]);

